   "example_zh": "当埃米尔·克雷佩林（Emil Kraepelin）——阿尔茨海默斯的导师——在他极具影响力的精神病学教科书1910年版中命名这种疾病时，他推测该病与当时的痴呆症不同，后者是老年认知衰退的统称。",
