   "def_zh": "干涉者；闯入者",
   "example": "It can be hard to forget that, when we route our words through those matrices, there may be someone else listening: since their inception, the wires have been tapped by operators, by eavesdroppers, by what Gleick calls a range of “invisible interlopers.” So we talk blindly into the receiver, and we’re never quite sure of where or how our words will land.",
