   "word": "monsoonal",
   "phonetic": "/mɒnˈsuːnəl/",
   "pos": "a.",
   "def_en": "Relating to or resembling a monsoon; characterized by heavy seasonal rains.",
   "def_zh": "季风般的；多季风雨的",
   "example": "I tried, but I was too small to lift you Up and out of that bathtub— Your two arms cut open, your two legs— You were January, bamboo shooting through darkness In that village, monsoonal and rude, that you stopped imagining Coming home to altogether— I was bad at math, I had my two small hands— Arrow fashioned from a jade comb telling me to go let go let— A small voice crying out for help for— What do you know— Hands gathering all that was leaving— All that was left— I ruined the plans you had for your life.",
   "example_zh": "我试过了，但我太小，无法把你从那浴缸里抬出来——你的双臂被割开，你的双腿——你就是那一月的竹子，刺穿黑暗，在那个村庄里，季风般粗暴，以至于你不再想象回到家乡——我数学很差，我有两只小手——用玉梳做成的箭矢告诉我放手、放手、放手——一个小声音呼救——你知道什么——双手拾起所有正在离去的东西——所有剩下的东西——我毁了你为我的人生计划。",
   "etymology": "monsoon（季风）+ -al（形容词后缀）；monsoon 源自阿拉伯语 mausim，意为“季节”",
   "tags": [
    "Poems",
    "ny_2026_11_09"
   ],
   "audio": ""
