   "def_zh": "意译；改写",
   "example": "Zvyagintsev paraphrased Gleb’s reaction to being drawn into Russia’s war effort: “Damn, why do I have to deal with this?” Gleb, he went on, “wants to stay on neutral ground, to not get involved, to keep from getting sucked into this nightmare.” Zvyagintsev and I met this summer in Jurmala, a charming Latvian resort town on the Baltic Sea.",
