   "example": "She indulges a fantasy of communicating with someone resembling her brother: “We liaise, distant energies / exchange.” A “channel” opens, through which she can reach out and even Prikryl initially describes the encounter at a distance: “A passerby notices her brother,” imagined as “always older, kinder, with a glamour / fled these thirty years.” Of course, the passerby isn’t him.",
