   "example": "(You hear it in the music, too; the Rolling Stones’ “Out of Time” isn’t the subtlest of needle drops.) McDonagh’s dialogue is famed for its staccato crackle, but here he slows the characters’ rhythms, as if to accommodate the diminution of Chris’s body and mind, and packs dead air around everyone’s lines.",
   "example_zh": "（你也能在音乐中听到它；滚石乐队的《时光流逝》并非最微妙的插入曲目。）麦克唐纳的对话以其断奏般的爆裂感著称，但在这里他放慢了角色的节奏，仿佛要适应克里斯身心功能的衰退，并在每个人的台词周围填满死寂的空白。",
