   "example": "In 1905, the magazine Telephony cautioned readers against the “hasty communication of tempestuous thoughts to the telephone girl.” Abusing the operator was apparently part of an epidemic of telephone behavior that Telephony deemed “the great ethical problem” of the day.",
   "example_zh": "1905年，《电话》杂志告诫读者不要“草率地向接线员传达情绪激烈的想法”。虐待接线员显然是当时一种电话行为流行病的一部分，《电话》杂志将其视为当时“重大的道德问题”。",
