   "pos": "n.",
   "def_en": "A small piece or amount of something, especially food; also used metaphorically for a small piece of interesting information.",
   "def_zh": "少量美食；有趣的小知识",
   "example": "Erdős described some of them as “marshmallows” and others as “acorns.” In a talk in February of this year, titled “Machine Assistance and the Future of Research Mathematics,” Tao quoted Erdős’s characterization of a marshmallow as “a tasty tidbit supplying a few moments of fleeting enjoyment,” and of an acorn as “requiring deep and subtle new insights from which a mighty oak can develop.”",
   "example_zh": "埃尔德什将其中一些描述为“棉花糖”，另一些为“橡子”。在今年二月题为“机器辅助与研究数学的未来”的演讲中，陶哲轩引用了埃尔德什对棉花糖的定义：“提供短暂享受片刻的美味小吃”，以及对橡子的定义：“需要深刻而微妙的新见解，从中才能茁壮成长成参天大树”。",
   "etymology": "tid（美味）+ bit（小块）：字面意为“美味的一口”",
