   "pos": "n.",
   "def_en": "The action of drying oneself with a towel; the act of using a towel.",
   "def_zh": "用毛巾擦拭；擦身",
   "example": "“Worthy worthy worthy.” In one of the opera’s lovelier ensemble arias, the ghosts praise “the things of the world,” enumerating the small, sticky details that they miss from human existence: “beerfroth,” “toweling off one’s clinging shirt post June rain.” Language, like irresolution, is a thing that belongs to the living world.",
   "example_zh": "“值得，值得，值得。”在歌剧最美妙的重唱咏叹调之一中，幽灵们赞美“世间的万物”，列举他们怀念的人类生活的琐碎黏腻细节：“啤酒泡沫”、“六月雨后擦去贴在身上的衬衫”。语言，像犹豫不决一样，属于活人的世界。",
   "etymology": "towel（毛巾）+ ing（动名词后缀），此处用作名词",
